/**
 * Black-and-white DeepSeek whale icons the proxy can serve in place of DSH's
 * own home-screen icons (`homeScreenIcon` setting). Rendered from the whale
 * path in DSH's favicon.svg. GENERATED by scripts/embed-home-icons.mjs from
 * assets/home-icons — do not edit by hand.
 */
import type { HomeScreenIcon } from './contract.ts'

const PNG_BASE64: Record<Exclude<HomeScreenIcon, 'dsh'>, Record<string, string>> = {
  black: {
    '/apple-touch-icon.png': '',
    '/icon-192.png': '',
    '/icon-512.png': '',
    '/icon-maskable-512.png': '',
  },
  white: {
    '/apple-touch-icon.png': '',
    '/icon-192.png': '',
    '/icon-512.png': '',
    '/icon-maskable-512.png': '',
  },
}

const decoded = new Map<string, Buffer>()

/**
 * The replacement PNG for one icon path, or undefined when DSH's own icon
 * should be served (the `dsh` choice, or a path that is not a home-screen icon).
 */
export function homeScreenIconPng(choice: HomeScreenIcon | undefined, pathname: string): Buffer | undefined {
  if (choice !== 'black' && choice !== 'white') return undefined
  const base64 = PNG_BASE64[choice][pathname]
  if (base64 === undefined) return undefined
  const key = choice + pathname
  let png = decoded.get(key)
  if (png === undefined) {
    png = Buffer.from(base64, 'base64')
    decoded.set(key, png)
  }
  return png
}

const TOUCH_ICON_LINK = /<link\b[^>]*\brel=["']?apple-touch-icon["']?[^>]*>/i

/**
 * Point the page's apple-touch-icon link at a URL unique to the chosen whale
 * (`/apple-touch-icon.png?v=black`). A phone, or a CDN that sets its own
 * browser cache lifetime, may still hold DSH's icon under the bare URL; a new
 * URL makes "Add to Home Screen" fetch the chosen one. Adds the link when the
 * page has none (DSH 0.2.1-rc.5). Leaves the page alone for `dsh`.
 */
export function pinHomeScreenIcon(html: string, choice: HomeScreenIcon | undefined): string {
  if (choice !== 'black' && choice !== 'white') return html
  const tag = `<link rel="apple-touch-icon" href="/apple-touch-icon.png?v=${choice}" />`
  if (TOUCH_ICON_LINK.test(html)) return html.replace(TOUCH_ICON_LINK, tag)
  const head = html.toLowerCase().indexOf('</head>')
  return head === -1 ? html : html.slice(0, head) + tag + html.slice(head)
}
